def longest_common_prefix(strs):
    """
    Finds the longest common prefix among a list of strings.

    Args:
        strs: A list of strings.

    Returns:
        The longest common prefix string. Returns an empty string if the list is
        empty, any string in the list is empty, or there is no common prefix.
    """
    if not strs:
        return ""

    for s in strs:
        if not s:
            return ""

    shortest_str = min(strs, key=len)
    prefix = ""

    for i, char in enumerate(shortest_str):
        is_common = True
        for other_str in strs:
            if other_str[i] != char:
                is_common = False
                break
        if is_common:
            prefix += char
        else:
            break
    return prefix
```

