def longest_common_prefix(strs):
    if not strs:
        return ""

    for s in strs:
        if not s:
            return ""

    # Sort the list of strings. The common prefix must be a prefix of
    # the first and last string after sorting.
    strs.sort()

    first_str = strs[0]
    last_str = strs[-1]

    common_prefix = []
    for i in range(min(len(first_str), len(last_str))):
        if first_str[i] == last_str[i]:
            common_prefix.append(first_str[i])
        else:
            break

    return "".join(common_prefix)
