def evaluate_rpn(tokens):
    stack = []
    for token in tokens:
        if token in ['+', '-', '*', '/']:
            operand2 = stack.pop()
            operand1 = stack.pop()
            if token == '+':
                stack.append(operand1 + operand2)
            elif token == '-':
                stack.append(operand1 - operand2)
            elif token == '*':
                stack.append(operand1 * operand2)
            elif token == '/':
                # Integer division that truncates toward zero
                # For example, -3 // 2 is -2 in Python, but we want -1
                result = operand1 / operand2
                if result < 0:
                    stack.append(int(result) + 1 if result != int(result) else int(result))
                else:
                    stack.append(int(result))
        else:
            stack.append(int(token))
    return stack[0]
