def longest_common_prefix(strs):
    if not strs:
        return ""

    for s in strs:
        if not s:
            return ""

    # Sort the list to easily find common prefix between the first and last
    # strings. The common prefix of the entire list must be a prefix of
    # the first and last strings after sorting.
    strs.sort()

    first_str = strs[0]
    last_str = strs[-1]
    common_prefix = ""

    for i in range(min(len(first_str), len(last_str))):
        if first_str[i] == last_str[i]:
            common_prefix += first_str[i]
        else:
            break

    return common_prefix
