                # We can achieve this by converting to float, dividing, and then truncating
                # or by using int() on the result of float division.
                # However, a simpler way for truncation towards zero for non-negative numbers
                # is standard //, and for negative numbers where the result is negative,
                # we want ceil if the result of true division is not an integer.
                # A robust way is to use int() on the true division result.
                stack.append(int(operand1 / operand2))
        else:
            stack.append(int(token))

