    stack = []
    for token in tokens:
        if token in ['+', '-', '*', '/']:
            operand2 = stack.pop()
            operand1 = stack.pop()
            if token == '+':
                stack.append(operand1 + operand2)
            elif token == '-':
                stack.append(operand1 - operand2)
            elif token == '*':
                stack.append(operand1 * operand2)
            elif token == '/':
                # Integer division that truncates toward zero
                # For example, -3 // 2 is -2 in Python, but we want -1
                # So we convert to float, divide, and then convert to int
                stack.append(int(float(operand1) / operand2))
        else:
            stack.append(int(token))
    return stack[0]

