def evaluate_rpn(tokens):
    stack = []
    for token in tokens:
        if token.isdigit() or (token.startswith('-') and token[1:].isdigit()):
            stack.append(int(token))
        else:
            operand2 = stack.pop()
            operand1 = stack.pop()
            if token == '+':
                stack.append(operand1 + operand2)
            elif token == '-':
                stack.append(operand1 - operand2)
            elif token == '*':
                stack.append(operand1 * operand2)
            elif token == '/':
                # Python's default division truncates toward negative infinity for negative numbers.
                # We need to truncate towards zero.
                if operand1 * operand2 < 0 and operand1 % operand2 != 0:
                    stack.append(-(abs(operand1) // abs(operand2)))
                else:
                    stack.append(operand1 // operand2)
    return stack[0]

```

